<script setup lang="ts">
import {authStorage} from "./authStorage";
import {computed,ref,toRaw,onMounted,onUnmounted,watch,nextTick} from 'vue';
import {type SF,type MF,type Spec,type Config,type DT,type RecordData,makeField,makeSubfield,prepareRecord,cleanRecord,cloneField,move,codesFor} from './catalog';
import VocabularyInput from './VocabularyInput.vue';
import IsbnLookup from './IsbnLookup.vue';
import UsersPage from './UsersPage.vue';
import AccountMenu from './AccountMenu.vue';
import {setUserScope} from './authStorage';
import {insertIsbn,type IsbnRow} from './isbn';
import HoldingsPanel from './HoldingsPanel.vue';
import AcquisitionsPage from './AcquisitionsPage.vue';
import KsuPage from './KsuPage.vue';
import StatisticsPage from './StatisticsPage.vue';
import ReadersPage from './ReadersPage.vue';
import CirculationPage from './CirculationPage.vue';
import VisitsPage from './VisitsPage.vue';
const readersPage=ref<InstanceType<typeof ReadersPage>|null>(null),visitCode=ref('');
async function openReader(id:number){page.value='readers';await nextTick();await readersPage.value?.open(id);}
function openVisit(code:string){visitCode.value=code;page.value='visits';}

const statisticsOpen=ref(false);
import WithdrawalsPage from './WithdrawalsPage.vue';
import VocabularySettings from './VocabularySettings.vue';
import SettingsTransfer from './SettingsTransfer.vue';
import {fieldName,subName,ru} from './ru';
const acquisitionsPage=ref<InstanceType<typeof AcquisitionsPage>|null>(null);
async function openKsuReceipt(id:number){if(!can('acquisitions.view')){error.value='Для просмотра поступления требуется право «Просмотр поступлений».';return;}page.value='acquisitions';await nextTick();await acquisitionsPage.value?.openReceipt(id);}
async function openKsuRecord(id:number){page.value='catalog';await edit({id} as RecordData);window.scrollTo(0,0);}
const moduleOpen=ref(false),deleteTarget=ref<RecordData|null>(null),deleteDialog=ref<HTMLDialogElement|null>(null);
watch(deleteTarget,async target=>{await nextTick();if(target){error.value='';deleteDialog.value?.showModal();}else deleteDialog.value?.close();});
const vocabularyEntries=ref<any[]>([]);
const username=ref(''),password=ref(''),csrf=ref(''),currentUser=ref<any>(null);
function can(permission:string){return currentUser.value?.role==='admin'||currentUser.value?.permissions.includes(permission);}
const connected=ref(false),busy=ref(false),error=ref(''),message=ref(''),page=ref('catalog');
const localFields=ref<Spec[]>([]),defaultConfig=ref<Config[]>([]),markerField:MF={tag:'000'},gostKind=ref<'single'|'component'>('single'),gostPreview=ref<any>(null),gostSource=ref('');
const dictionary=ref<Spec[]>([]),types=ref<DT[]>([]),records=ref<RecordData[]>([]),q=ref(''),filterType=ref(0),offset=ref(0);
const profile=ref<DT>({id:0,name:'',config:[]}),fieldQuery=ref(''),editor=ref<RecordData|null>(null),baseline=ref('');
watch(()=>page.value==='catalog'&&editor.value!==null,opened=>{
 if(opened)window.scrollTo({top:0,left:0,behavior:'instant'});
},{flush:'post'});
const codedOpen=ref(false),recordTab=ref('description'),creationKey=ref('');
const pendingRecord=ref<any>(null);
try{pendingRecord.value=JSON.parse(authStorage.getItem('pending-record')||'null');}catch{}
function clearPendingRecord(){authStorage.removeItem('pending-record');pendingRecord.value=null;}
async function acceptSaved(saved:any){editor.value={id:saved.id,type_id:saved.type_id,version:saved.version,marc:saved.marc};prepareRecord(editor.value!,activeType.value,specs.value);baseline.value=JSON.stringify(cleanRecord(editor.value!));rawOpen.value=false;await loadVocabulary();message.value='Запись сохранена'+(saved.warnings.length?' · '+saved.warnings.map(localError).join('; '):'');await search();}
async function postNewRecord(body:any){authStorage.setItem('pending-record',JSON.stringify(body));pendingRecord.value=body;let saved;try{saved=await api('/records','POST',body);}catch(e){const status=(e as any).status;if(status>=400&&status<500)clearPendingRecord();throw e;}clearPendingRecord();await acceptSaved(saved);recordTab.value=body.initial_acquisition?'holdings':'description';}
async function recoverRecord(){await run(async()=>{await postNewRecord(pendingRecord.value);page.value='catalog';});}

const expanded=ref(new Set<number>()),addCode=ref<Record<number,string>>({}),raw=ref(''),rawOpen=ref(false),confirmClose=ref(false);
const menu=ref<{x:number,y:number,field:MF,sub?:SF}|null>(null),referenceTag=ref('245'),showObsolete=ref(false);
const ids=new WeakMap<object,number>();let nextId=0;
function uid(o:object){o=toRaw(o);if(!ids.has(o))ids.set(o,++nextId);return ids.get(o)!;}
const officialSpecs=computed(()=>Object.fromEntries(dictionary.value.map(f=>[f.tag,f])));
const localSpecs=computed(()=>Object.fromEntries(localFields.value.map(f=>[f.tag,f])));
const specs=computed(()=>{const config=page.value==='types'?profile.value.config:activeType.value?.config||[];return {...officialSpecs.value,...Object.fromEntries(config.filter(c=>c.local&&localSpecs.value[c.tag]).map(c=>[c.tag,localSpecs.value[c.tag]]))};});
const available=computed(()=>(page.value==='types'?Object.values({...officialSpecs.value,...localSpecs.value}):dictionary.value).filter(f=>(showObsolete.value||!f.obsolete)&&(f.tag+' '+(f.local?f.label:fieldName(f.tag,f.label))+' '+f.label).toLowerCase().includes(fieldQuery.value.toLowerCase())));
const activeType=computed(()=>types.value.find(t=>t.id===editor.value?.type_id));
const visible=computed(()=>activeType.value?.config.flatMap(c=>c.tag==='000'?[markerField]:editor.value?.marc.fields.filter(f=>f.tag===c.tag)||[])||[]);
const hidden=computed(()=>editor.value?cleanRecord(editor.value).marc.fields.filter(f=>!activeType.value?.config.some(c=>c.tag===f.tag)).length:0);
const dirty=computed(()=>!!editor.value&&JSON.stringify(cleanRecord(editor.value))!==baseline.value);
const filled=computed(()=>visible.value.filter(f=>f.value?.trim()||f.subfields?.some(s=>s.value.trim()&&!(f.tag==='084'&&s.code==='2'))).length);
const refSpec=computed(()=>officialSpecs.value[referenceTag.value]);
function fieldLabel(tag:string){return activeType.value?.config.find(c=>c.tag===tag)?.label||fieldName(tag,specs.value[tag]?.label);}
function sfLabel(f:MF,s:SF){const label=specs.value[f.tag]?.subfields.find(d=>d.code===s.code)?.label||'';return specs.value[f.tag]?.local?label||('Подполе $'+s.code):subName(f.tag,s.code,label);}
function required(f:MF){return !!activeType.value?.config.find(c=>c.tag===f.tag)?.required;}
function orderedSubs(f:MF){const config=activeType.value?.config.find(c=>c.tag===f.tag);const order=config?.subfields.length?config.subfields:(specs.value[f.tag]&&config?codesFor(specs.value[f.tag],config):[]);return [...(f.subfields||[])].filter(s=>!config?.local||!config.subfields.length||config.subfields.includes(s.code)).sort((a,b)=>{const ai=order.indexOf(a.code),bi=order.indexOf(b.code);return (ai<0?999:ai)-(bi<0?999:bi);});}
function primary(f:MF){return orderedSubs(f)[0];}
function extra(f:MF){return orderedSubs(f).slice(1);}
function toggleDetails(f:MF){const id=uid(f);if(expanded.value.has(id))expanded.value.delete(id);else expanded.value.add(id);}
function options(f:MF){const cfg=activeType.value?.config.find(c=>c.tag===f.tag);return (specs.value[f.tag]?.subfields||[]).filter(s=>(!cfg?.subfields.length||cfg.subfields.includes(s.code))&&(s.repeatable||!f.subfields?.some(x=>x.code===s.code)));}
function localError(detail:unknown):string{
 if(Array.isArray(detail))return detail.map(d=>typeof d==='object'?'Проверьте формат введённых данных.':localError(d)).join('\n');
 let s=String(detail);const map:Record<string,string>={'Administrator key required':'Неверный ключ доступа. Проверьте ключ и попробуйте снова.','Type name already exists':'Тип с таким названием уже существует.','Name is empty':'Введите название типа документа.','Record changed or deleted; reload before saving':'Запись изменена другим пользователем. Откройте актуальную версию и согласуйте изменения.','required by document type':'обязательное поле — введите значение','not repeatable':'повторение не допускается','Leader must contain 24 ASCII characters':'Маркер записи должен содержать 24 символа ASCII','unknown/local field preserved':'локальное поле сохранено','unknown subfield preserved':'локальное подполе сохранено','obsolete':'устаревший элемент','Unknown document type':'Выберите тип документа','Record not found':'Запись не найдена. Возможно, она уже удалена.','Version required':'Не указана версия записи','Duplicate profile fields':'Поле выбрано в настройках несколько раз'};
 for(const [a,b] of Object.entries(map))s=s.replaceAll(a,b);
 return s.replace(/indicator (\d) must be one ASCII character/g,'индикатор $1 должен содержать один символ ASCII').replace(/control field must have only value/g,'контрольное поле должно содержать только значение').replace(/data field needs subfields, not value/g,'поле должно содержать подполя вместо одного значения').replace(/invalid indicator (\d):/g,'недопустимое значение индикатора $1:').replace(/expected (\d+) characters/g,'необходимо $1 символов');
}
async function api(path:string,method='GET',body?:unknown){const r=await fetch('/api'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf.value},body:body===undefined?undefined:JSON.stringify(body)});if(r.status===204)return null;const data=await r.json();if(!r.ok){if(r.status===401&&path!=='/auth/login'){signedOut();}throw Object.assign(Error(localError(data.detail)),{status:r.status});}return data;}
function signedOut(){connected.value=false;currentUser.value=null;csrf.value='';editor.value=null;pendingRecord.value=null;records.value=[];menu.value=null;rawOpen.value=false;confirmClose.value=false;deleteTarget.value=null;setUserScope(null);page.value='catalog';message.value='Войдите с логином и паролем.';}
async function logout(){if(dirty.value&&!window.confirm('Выйти без сохранения изменений записи?'))return;await run(async()=>{await api('/auth/logout','POST');signedOut();});}
async function loadSession(data:any){currentUser.value=data.user;csrf.value=data.csrf_token;setUserScope(data.user.id);try{pendingRecord.value=JSON.parse(authStorage.getItem('pending-record')||'null');}catch{pendingRecord.value=null;}if(can('catalog.view')){const d=await api('/dictionary');dictionary.value=d.fields;localFields.value=d.local_fields||[];defaultConfig.value=d.default_config||[];types.value=await api('/types');selectProfile(types.value[0]);await search();}page.value=can('catalog.view')?'catalog':can('readers.registry.view')?'readers':can('loans.view_own')?'circulation':'visits';if(location.hash==='#circulation'&&(can('circulation.issue')||can('circulation.return')||can('loans.view_own')))page.value='circulation';if(location.hash==='#readers'&&can('readers.registry.view'))page.value='readers';if(location.hash==='#visits'&&(can('visits.view')||can('visits.record')))page.value='visits';editor.value=null;moduleOpen.value=false;connected.value=true;}
async function restoreSession(){try{await loadSession(await api('/auth/me'));}catch{signedOut();}}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';message.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:String(e);}finally{busy.value=false;}}
async function login(){await run(async()=>{const data=await api('/auth/login','POST',{username:username.value,password:password.value});password.value='';await loadSession(data);});}
function vocabSettings(f:MF,code:string){const configured=activeType.value?.config.find(c=>c.tag===f.tag)?.vocabularies?.[code];return configured||(f.tag==='097'&&code==='b'?{auto_add:false,allow_edit:true}:undefined);}
function vocabEntries(f:MF,code:string){return vocabularyEntries.value.filter(e=>e.tag===f.tag&&e.code===code);}
async function loadVocabulary(){const id=editor.value?.type_id;vocabularyEntries.value=[];if(!id)return;try{const entries=await api('/types/'+id+'/vocabulary');if(editor.value?.type_id===id)vocabularyEntries.value=entries;}catch(e){error.value=String(e);}}
watch(()=>editor.value?.type_id,loadVocabulary);
watch(page,()=>{if(page.value==='catalog'&&editor.value)loadVocabulary();});
async function search(){records.value=await api(`/records?q=${encodeURIComponent(q.value)}&offset=${offset.value}${filterType.value?'&type_id='+filterType.value:''}`);}
function selectProfile(t?:DT){profile.value=t?JSON.parse(JSON.stringify(t)):{id:0,name:'',config:JSON.parse(JSON.stringify(defaultConfig.value))};}
function toggle(tag:string){const i=profile.value.config.findIndex(c=>c.tag===tag);if(i>=0)profile.value.config.splice(i,1);else profile.value.config.push({tag,label:localSpecs.value[tag]?.label||'',local:!!localSpecs.value[tag],required:tag==='000',subfields:[]});}
async function saveProfile(){await run(async()=>{const {id,...body}=profile.value;profile.value=await api('/types'+(id?'/'+id:''),id?'PUT':'POST',body);types.value=await api('/types');if(editor.value){prepareRecord(editor.value,activeType.value,specs.value);await loadVocabulary();}message.value='Настройки сохранены. Рабочий лист обновлён.';});}
async function refreshSettings(){await run(async()=>{types.value=await api('/types');selectProfile(types.value.find(t=>t.id===profile.value.id)||types.value[0]);if(editor.value){prepareRecord(editor.value,activeType.value,specs.value);await loadVocabulary();}});}
function configChanged(event:Event){const id=Number((event.target as HTMLSelectElement).value);selectProfile(types.value.find(t=>t.id===id));}
function fillOperator(){
 if(!editor.value||editor.value.id||!currentUser.value)return;
 let fields=editor.value.marc.fields.filter(f=>f.tag==='097');
 if(!fields.length&&activeType.value?.config.some(c=>c.tag==='097'&&c.local)){
  const field:MF={tag:'097',ind1:' ',ind2:' ',subfields:[]};editor.value.marc.fields.push(field);fields=[field];
 }
 for(const [index,f] of fields.entries()){
  f.subfields=(f.subfields||[]).filter(s=>s.code!=='b');
  if(index===0)f.subfields.push({code:'b',value:currentUser.value.display_name});
 }
}
function startRecord(){if(pendingRecord.value){error.value='Сначала восстановите незавершённое сохранение записи.';return;}recordTab.value='description';creationKey.value=crypto.randomUUID();editor.value={type_id:types.value[0]?.id||0,marc:{leader:'00000nam a2200000   4500',fields:[]}};prepareRecord(editor.value,activeType.value,specs.value);fillOperator();baseline.value=JSON.stringify(cleanRecord(editor.value));expanded.value.clear();rawOpen.value=false;codedOpen.value=false;gostPreview.value=null;gostKind.value='single';page.value='catalog';error.value='';message.value='';}
function applyIsbn(rows:IsbnRow[],selected:boolean[]){
 if(!editor.value||editor.value.id)return;
 insertIsbn(rows,editor.value.marc.fields,selected,tag=>makeField(specs.value[tag],activeType.value?.config.find(c=>c.tag===tag)||{tag,label:'',required:false,subfields:[]}));
 prepareRecord(editor.value,activeType.value,specs.value);gostPreview.value=null;
 message.value='Сведения вставлены. Проверьте описание перед сохранением; дополнительные поля доступны в полной записи.';
}
async function edit(r:RecordData){await run(async()=>{recordTab.value='description';editor.value=await api('/records/'+r.id);prepareRecord(editor.value!,activeType.value,specs.value);baseline.value=JSON.stringify(cleanRecord(editor.value!));expanded.value.clear();rawOpen.value=false;codedOpen.value=false;gostPreview.value=null;gostKind.value=activeType.value?.name==='Научная статья'?'component':'single';});}
function changeType(){gostPreview.value=null;gostKind.value=activeType.value?.name==='Научная статья'?'component':'single';if(editor.value){prepareRecord(editor.value,activeType.value,specs.value);}}
function openCatalog(){page.value='catalog';closeEditor();if(connected.value)run(search);}
function closeEditor(){if(dirty.value){confirmClose.value=true;return;}editor.value=null;rawOpen.value=false;}
async function saveRecord(){if(!can('catalog.edit'))return;await run(async()=>{if(!editor.value)return;if(pendingRecord.value){throw Error('Восстановите незавершённое сохранение кнопкой выше. Повтор будет отправлен с исходными данными.');}const {id,...body}=cleanRecord(editor.value);if(id){await acceptSaved(await api('/records/'+id,'PUT',body));}else{await postNewRecord({...body,request_key:creationKey.value,initial_acquisition:null});}});}

async function deleteRecord(){if(!deleteTarget.value?.id||busy.value)return;const target=deleteTarget.value;await run(async()=>{await api('/records/'+target.id+'?version='+target.version,'DELETE');if(editor.value?.id===target.id){editor.value=null;rawOpen.value=false;}deleteTarget.value=null;if(records.value.length===1&&records.value[0]?.id===target.id&&offset.value>0)offset.value=Math.max(0,offset.value-50);await search();message.value='Запись №'+target.id+' удалена';});}
function title(r:RecordData){return r.marc.fields.find(f=>f.tag==='245')?.subfields?.filter(s=>s.code==='a').map(s=>s.value.trim()).filter(Boolean).join(' ')||'Без заглавия';}
function author(r:RecordData){return r.marc.fields.find(f=>f.tag==='100')?.subfields?.find(s=>s.code==='a')?.value||'—';}
function openMenu(e:MouseEvent,f:MF,sub?:SF){if(!can('catalog.edit'))return;e.preventDefault();menu.value={x:Math.max(8,Math.min(e.clientX,window.innerWidth-285)),y:Math.max(8,Math.min(e.clientY,window.innerHeight-235)),field:f,sub};}
function canRepeat(){if(!menu.value||technical(menu.value.field,menu.value.sub))return false;const {field,sub}=menu.value;return sub?!!specs.value[field.tag]?.subfields.find(s=>s.code===sub.code)?.repeatable:!!specs.value[field.tag]?.repeatable;}
function canRemove(){if(!menu.value||technical(menu.value.field,menu.value.sub))return false;return menu.value.sub?!(required(menu.value.field)&&menu.value.field.subfields?.length===1):!required(menu.value.field);}
function duplicate(){if(!menu.value||!canRepeat()||!editor.value)return;const {field,sub}=menu.value;if(sub){const i=field.subfields!.indexOf(sub);field.subfields!.splice(i+1,0,{...sub});expanded.value.add(uid(field));}else{const i=editor.value.marc.fields.indexOf(field);editor.value.marc.fields.splice(i+1,0,cloneField(field));}menu.value=null;}
function remove(){if(!menu.value||!canRemove()||!editor.value)return;const {field,sub}=menu.value;if(sub)field.subfields!.splice(field.subfields!.indexOf(sub),1);else editor.value.marc.fields.splice(editor.value.marc.fields.indexOf(field),1);menu.value=null;}
function addSub(f:MF){const code=addCode.value[uid(f)]||options(f)[0]?.code;if(!code)return;f.subfields??=[];f.subfields.push(makeSubfield(code));expanded.value.add(uid(f));addCode.value[uid(f)]='';}
function technical(f:MF,sub?:SF){return ['000','001','005','008'].includes(f.tag)||(f.tag==='990'&&specs.value[f.tag]?.local&&(!sub||['d','e','f'].includes(sub.code)));}
function codedValue(){return editor.value?.marc.fields.find(f=>f.tag==='008')?.value||'';}
function codedPart(start:number,length:number){return codedValue().slice(start,start+length);}
function setCoded(start:number,length:number,event:Event){
 if(!editor.value)return;
 let f=editor.value.marc.fields.find(f=>f.tag==='008');
 if(!f){f={tag:'008',value:''};editor.value.marc.fields.push(f);}
 if(f.value&&f.value.length!==40){error.value='В поле 008 не 40 символов. Проверьте исходную запись в служебных данных.';return;}
 const date=new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Almaty',year:'2-digit',month:'2-digit',day:'2-digit'}).format(new Date()).replaceAll('-','');
 const value=f.value||date+'|'.repeat(34);
 const part=(event.target as HTMLInputElement).value.padEnd(length,' ').slice(0,length);
 f.value=value.slice(0,start)+part+value.slice(start+length);
}
async function buildGost(){await run(async()=>{const marc=cleanRecord(editor.value!).marc;gostPreview.value=await api('/gost/preview','POST',{marc,kind:gostKind.value});gostSource.value=JSON.stringify(marc)+gostKind.value;});}
const gostStale=computed(()=>!!editor.value&&gostSource.value!==JSON.stringify(cleanRecord(editor.value).marc)+gostKind.value);
function restore(tag:string){const cfg=activeType.value?.config.find(c=>c.tag===tag);if(editor.value&&cfg)editor.value.marc.fields.push(makeField(specs.value[tag],cfg));}
function openRaw(){raw.value=JSON.stringify(cleanRecord(editor.value!).marc,null,2);rawOpen.value=true;}
function applyRaw(){try{const data=JSON.parse(raw.value);if(!data||typeof data.leader!=='string'||!Array.isArray(data.fields)||data.fields.some((f:MF)=>!f||typeof f.tag!=='string'||!/^\d{3}$/.test(f.tag)||(f.value!==undefined&&typeof f.value!=='string')||(f.ind1!==undefined&&typeof f.ind1!=='string')||(f.ind2!==undefined&&typeof f.ind2!=='string')||(f.subfields!==undefined&&(!Array.isArray(f.subfields)||f.subfields.some(s=>!s||typeof s.code!=='string'||typeof s.value!=='string')))))throw Error('Проверьте структуру записи: нужны маркер leader и массив полей fields.');editor.value!.marc=data;prepareRecord(editor.value!,activeType.value,specs.value);rawOpen.value=false;error.value='';}catch(e){error.value='Не удалось прочитать запись. '+String(e);}}
function nextInput(e:KeyboardEvent){if(e.shiftKey||e.ctrlKey||e.metaKey)return;e.preventDefault();const inputs=Array.from(document.querySelectorAll<HTMLInputElement>('.value-input:not([readonly])'));const i=inputs.indexOf(e.target as HTMLInputElement);inputs[i+1]?.focus();}
function dismiss(){menu.value=null;}
function onKey(e:KeyboardEvent){if(e.key==='Escape'){menu.value=null;rawOpen.value=false;confirmClose.value=false;}if((e.ctrlKey||e.metaKey)&&e.key==='s'&&editor.value&&!document.querySelector('dialog[open]')){e.preventDefault();if(!busy.value&&!rawOpen.value)saveRecord();}}
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue='';}}
onMounted(()=>{restoreSession();window.addEventListener('click',dismiss);window.addEventListener('keydown',onKey);window.addEventListener('resize',dismiss);window.addEventListener('scroll',dismiss,true);window.addEventListener('beforeunload',beforeUnload);});
onUnmounted(()=>{window.removeEventListener('click',dismiss);window.removeEventListener('keydown',onKey);window.removeEventListener('resize',dismiss);window.removeEventListener('scroll',dismiss,true);window.removeEventListener('beforeunload',beforeUnload);});
</script>
<template>
<div class="app-shell">
<aside v-if="connected" class="sidebar"><div class="brand"><span class="brand-icon">Б</span><div>Библиотека<small>Рабочее место каталогизатора</small></div></div><div class="nav-caption">МОДУЛИ БИБЛИОТЕКИ</div><nav class="module-nav" aria-label="Основная навигация"><div v-if="can('catalog.view')" class="module-nav-row"><button class="module-link" :class="{active:page==='catalog'}" @click="openCatalog" aria-label="Каталогизация и классификация"><span class="module-icon" aria-hidden="true">▤</span><span class="module-label">Каталогизация<br><span class="module-second">и классификация</span></span></button><button class="module-expand" :aria-expanded="moduleOpen" aria-controls="catalog-submenu" :aria-label="moduleOpen?'Скрыть подразделы каталогизации':'Показать подразделы каталогизации'" @click="moduleOpen=!moduleOpen">{{moduleOpen?'▾':'▸'}}</button></div><div v-show="moduleOpen" id="catalog-submenu" class="module-submenu"><button v-if="can('settings.edit')" :class="{active:page==='types'}" @click="page='types'">☷ <span>Настройка ввода</span></button><button :class="{active:page==='reference'}" @click="page='reference'">▧ <span>Справочник полей</span></button></div><button v-if="can('acquisitions.view')" class="module-link" :class="{active:page==='acquisitions'}" @click="page='acquisitions'" aria-label="Поступления"><span class="module-icon" aria-hidden="true">↙</span><span class="module-label">Поступления</span></button><button v-if="can('ksu.view')" class="module-link" :class="{active:page==='ksu'}" @click="page='ksu'" aria-label="КСУ"><span class="module-icon" aria-hidden="true">▦</span><span class="module-label">КСУ</span></button><button v-if="can('withdrawals.view')" class="module-link" :class="{active:page==='withdrawals'}" @click="page='withdrawals'" aria-label="Списание"><span class="module-icon" aria-hidden="true">↗</span><span class="module-label">Списание</span></button><button v-if="can('circulation.issue')||can('circulation.return')||can('circulation.view_any_history')||can('circulation.view_own_history')||can('loans.view_own')||can('reservations.manage')||can('fines.manage')||can('incidents.manage')||can('circulation.settings')" class="module-link" :class="{active:page==='circulation'}" @click="page='circulation'"><span class="module-icon">⇄</span><span class="module-label">Книговыдача</span></button><button v-if="can('readers.registry.view')" class="module-link" :class="{active:page==='readers'}" @click="page='readers'"><span class="module-icon">♙</span><span class="module-label">Читатели</span></button><button v-if="can('visits.record')||can('visits.view')" class="module-link" :class="{active:page==='visits'}" @click="visitCode='';page='visits'"><span class="module-icon">↪</span><span class="module-label">Посещения</span></button><div v-if="can('statistics.view')"><div class="module-nav-row"><button class="module-link" :class="{active:page==='statistics'}" @click="page='statistics';statisticsOpen=true"><span class="module-icon">▥</span><span class="module-label">Статистика</span></button><button class="module-expand" :aria-expanded="statisticsOpen" aria-controls="statistics-submenu" aria-label="Подразделы статистики" @click="statisticsOpen=!statisticsOpen">{{statisticsOpen?'▾':'▸'}}</button></div><div v-show="statisticsOpen" id="statistics-submenu" class="module-submenu"><button :class="{active:page==='statistics'}" @click="page='statistics'">Работа сотрудников</button></div></div><button v-if="currentUser?.role==='admin'" class="module-link" :class="{active:page==='users'}" @click="page='users'">Пользователи и права</button></nav><div class="sidebar-bottom"><span class="online-dot"></span> Локальный каталог<small>Библиографический формат MARC21</small></div></aside>
<div class="workspace" :style="!connected?{marginLeft:0}:{}"><header class="topbar"><span>Библиотека <span class="crumb">/</span> {{page==='circulation'?'Книговыдача':page==='readers'?'Читатели':page==='visits'?'Посещения':page==='statistics'?'Статистика · Работа сотрудников':page==='ksu'?'КСУ · Поступления':page==='users'?'Пользователи и права':page==='withdrawals'?'Списание':page==='acquisitions'?'Поступления':'Каталогизация и классификация'}}</span><div v-if="connected" class="user-chip"><span>{{currentUser.display_name}} · {{currentUser.role==='admin'?'Администратор':currentUser.role==='viewer'?'Наблюдатель':currentUser.role==='reader'?'Читатель':currentUser.role==='manager'?'Руководитель':'Библиотекарь'}}</span><AccountMenu :api="api" @changed="signedOut" /><button :disabled="busy" @click="logout">Выйти</button></div></header>
<main>
<form v-if="!connected" class="login card" @submit.prevent="login"><div class="eyebrow">ДОБРО ПОЖАЛОВАТЬ</div><h1>Ваш библиотечный каталог</h1><p>Создавайте описания документов и настраивайте рабочие листы для каждого типа.</p><label>Логин<input v-model="username" autocomplete="username" required maxlength="80" autofocus></label><label>Пароль<input v-model="password" type="password" autocomplete="current-password" required maxlength="256"></label><button class="primary" :disabled="busy">Войти в каталог →</button></form>
<template v-else>
<div v-if="pendingRecord&&can('catalog.edit')" class="pending-note"><strong>Незавершённое сохранение новой записи</strong><p>Восстановите результат исходной операции. Повторный запрос не создаст ещё одну запись или экземпляры.</p><button :disabled="busy" @click="recoverRecord">Проверить и восстановить запись</button></div>
<section v-if="page==='catalog'&&!editor">
<div class="page-heading"><div><div class="eyebrow">КАТАЛОГИЗАЦИЯ И КЛАССИФИКАЦИЯ</div><h1>Каталог записей</h1><p>Все библиографические описания в одном месте.</p></div><button v-if="can('catalog.edit')" class="primary" @click="startRecord">＋ Создать запись</button></div>
<form class="search-bar card" @submit.prevent="offset=0;run(search)"><input v-model="q" placeholder="Название, автор, УДК, ББК, рубрика, инвентарный номер или штрихкод" aria-label="Поиск"><select v-model="filterType" aria-label="Тип документа для поиска"><option :value="0">Все типы документов</option><option v-for="t in types" :value="t.id">{{t.name}}</option></select><button :disabled="busy">Найти</button></form>
<div class="card table-wrap"><table class="catalog-table"><thead><tr><th>Документ</th><th>Автор</th><th>Тип документа</th><th>Номер</th><th><span class="sr-only">Действия</span></th></tr></thead><tbody><tr v-for="r in records" :key="r.id"><td><button class="record-title" @click="edit(r)"><span class="document-icon">▤</span>{{title(r)}}</button></td><td>{{author(r)}}</td><td><span class="pill">{{types.find(t=>t.id===r.type_id)?.name}}</span></td><td class="muted">{{r.id}}</td><td><button v-if="can('catalog.delete')" class="danger-link" :disabled="busy" :aria-label="'Удалить запись №'+r.id" @click="deleteTarget=r">Удалить</button></td></tr></tbody></table><div class="empty" v-if="!records.length"><span>▤</span><h2>Здесь появятся ваши записи</h2><p>Создайте описание документа или измените условия поиска.</p><button v-if="can('catalog.edit')" @click="startRecord">Создать первую запись</button></div><div class="table-footer"><span>{{records.length?'Показаны записи '+(offset+1)+'–'+(offset+records.length):'Нет записей'}}</span><div><button :disabled="offset===0||busy" @click="offset-=50;run(search)">← Назад</button><button :disabled="records.length<50||busy" @click="offset+=50;run(search)">Далее →</button></div></div></div>
</section>
<section v-if="page==='catalog'&&editor" class="editor">
<div class="page-heading"><div><button class="back-link" @click="closeEditor">← К списку записей</button><h1>{{editor.id?'Редактирование записи':'Новая запись'}}</h1><p>{{editor.id?'Запись № '+editor.id+' · ':''}}<span :class="{'unsaved':dirty}">{{dirty?'Есть несохранённые изменения':'Рабочий лист готов к заполнению'}}</span></p></div><div class="record-actions"><IsbnLookup v-if="!editor.id&&!rawOpen&&can('catalog.edit')" :api="api" :fields="editor.marc.fields" @insert="applyIsbn" /><button v-if="editor.id&&can('catalog.delete')" class="danger-link" :disabled="busy" @click="deleteTarget=editor">Удалить запись</button><button v-if="can('catalog.edit')" class="primary" :disabled="busy||rawOpen" @click="saveRecord">✓ Сохранить запись</button></div></div>
<div v-if="editor.id" class="record-tabs"><button :class="{active:recordTab==='description'}" @click="recordTab='description'">Описание документа</button><button :class="{active:recordTab==='holdings'}" @click="recordTab='holdings'">Экземпляры</button></div>
<HoldingsPanel v-if="editor.id&&recordTab==='holdings'" :canEdit="can('copies.edit')" :recordId="editor.id" :title="title(editor)" :api="api" />
<section v-if="!can('catalog.edit')&&recordTab==='description'" class="card table-wrap"><p class="profile-note">Режим просмотра</p><table><thead><tr><th>Код</th><th>Поле</th><th>Значение</th></tr></thead><tbody><template v-for="f in cleanRecord(editor).marc.fields"><tr v-if="f.value!==undefined"><td>{{f.tag}}</td><td>{{fieldLabel(f.tag)}}</td><td>{{f.value}}</td></tr><tr v-for="s in f.subfields"><td>{{f.tag}}${{s.code}}</td><td>{{sfLabel(f,s)}}</td><td>{{s.value}}</td></tr></template></tbody></table></section>
<fieldset class="plain-fieldset" v-show="recordTab==='description'&&can('catalog.edit')" :disabled="!can('catalog.edit')"><p v-if="!can('catalog.edit')">Режим просмотра. Изменение описания недоступно.</p>

<p class="profile-note">Сохранение описания не создаёт экземпляры или поступления. Имеющийся фонд добавляется в разделе «Экземпляры» сохранённой записи, новые партии — во вкладке «Поступления» бокового меню.</p>
<div class="worksheet-toolbar card"><label>Тип документа<select v-model="editor.type_id" @change="changeType" aria-label="Тип документа"><option v-for="t in types" :value="t.id">{{t.name}}</option></select></label><div class="worksheet-status"><strong>{{filled}} <span>/ {{visible.length}}</span></strong><small>строк заполнено</small></div><button v-if="can('settings.edit')" class="text-button" @click="page='types';selectProfile(activeType)">⚙ Настроить рабочий лист</button></div>
<p class="profile-note">Служебные номера и даты заполняются при сохранении. В новой записи оператор заполняется из ФИО текущего пользователя. Это значение можно изменить вручную.</p><p class="profile-note" v-if="activeType?.config.some(c=>c.local)">Рабочий лист MARCSQL · Коды и локальные значения сохранены по вашему образцу. Дополнительные строки предназначены для описания по ГОСТ.</p><div class="sheet-hint"><span>↳</span> Вводите значения в правой колонке. <b>Enter</b> — следующая строка. <b>Правый клик</b> или <b>⋯</b> — действия с полем.<span class="required-legend">* обязательное поле</span></div>
<div class="card table-wrap worksheet" :class="{compact:activeType?.config.some(c=>c.local)}"><table><colgroup><col class="code-col"><col class="name-col"><col></colgroup><thead><tr><th>Код</th><th>Название строки</th><th>Значение</th></tr></thead>
<tbody v-for="f in visible" :key="uid(f)" :data-field="f.tag">
<tr class="field-row" @contextmenu="openMenu($event,f)"><td class="code">{{f.tag}}<span v-if="specs[f.tag]?.local&&primary(f)" class="subcode-inline"> ${{primary(f)!.code}}</span><small v-if="visible.filter(x=>x.tag===f.tag).length>1">{{visible.filter(x=>x.tag===f.tag).indexOf(f)+1}}/{{visible.filter(x=>x.tag===f.tag).length}}</small></td><td><div class="field-name">{{specs[f.tag]?.local&&primary(f)?sfLabel(f,primary(f)!):fieldLabel(f.tag)}}<small v-if="technical(f,primary(f))" class="auto-label">Автоматически</small><span v-if="required(f)" class="asterisk">*</span><span v-if="specs[f.tag]?.repeatable" class="repeat-badge" title="Поле можно повторять">↻</span></div><button v-if="Number(f.tag)>=10&&!specs[f.tag]?.local" class="expand-button" @click="toggleDetails(f)" :aria-expanded="expanded.has(uid(f))">{{expanded.has(uid(f))?'▾ Свернуть подполя':'▸ Подполя и уточнения'}} <span v-if="extra(f).length">{{extra(f).length}}</span></button></td><td><div class="value-cell"><input v-if="f.tag==='000'" readonly class="value-input" :value="editor.marc.leader[5]" maxlength="1" aria-label="000 Маркер записи" @keydown.enter="nextInput"><VocabularyInput v-else-if="Number(f.tag)<10&&!technical(f)" v-model="f.value!" :ariaLabel="fieldLabel(f.tag)" :settings="vocabSettings(f,'_')" :entries="vocabEntries(f,'_')" @enter="nextInput" /><input v-else-if="Number(f.tag)<10" :readonly="technical(f)" class="value-input" v-model="f.value" :aria-label="fieldLabel(f.tag)" :placeholder="technical(f)?'Автоматически при сохранении':'Введите значение'" @keydown.enter="nextInput"><VocabularyInput v-else-if="primary(f)" :readonly="technical(f,primary(f))" v-model="primary(f)!.value" :ariaLabel="f.tag+' '+sfLabel(f,primary(f)!)" :placeholder="sfLabel(f,primary(f)!)" :settings="vocabSettings(f,primary(f)!.code)" :entries="vocabEntries(f,primary(f)!.code)" @enter="nextInput" /><button v-else @click="addSub(f)">＋ Добавить значение</button><button v-if="f.tag==='008'" @click="codedOpen=!codedOpen" :aria-expanded="codedOpen">Настроить характеристики</button><button class="dots" :aria-label="'Действия с полем '+f.tag" @click.stop="openMenu($event,f)">⋯</button></div></td></tr>
<tr v-if="f.tag==='008'&&codedOpen"><td colspan="3"><section class="coded-panel"><h3>Характеристики документа</h3><p>Дата создания устанавливается при сохранении. Для новой записи год и язык берутся из заполненных полей, если характеристики ещё не заданы. После сохранения уточняйте их здесь. Остальные позиции исходной строки сохраняются.</p>
<label>Характер даты<select :value="codedPart(6,1)||'|'" @change="setCoded(6,1,$event)"><option v-for="item in [['|','Не кодировать'],['s','Один год издания'],['m','Диапазон лет'],['n','Дата неизвестна'],['t','Издание и авторское право'],['r','Переиздание и оригинал'],['c','Продолжается'],['d','Прекращено'],['u','Статус неизвестен'],['e','Точная дата'],['i','Даты коллекции'],['k','Основные даты коллекции'],['p','Распространение и производство'],['q','Предположительные даты'],['b','До нашей эры']]" :value="item[0]">{{item[1]}}</option></select></label>
<label>Первый год (4 позиции)<input :value="codedPart(7,4)" maxlength="4" placeholder="2026 или uuuu" @change="setCoded(7,4,$event)"></label>
<label>Вторая дата (4 позиции)<input :value="codedPart(11,4)" maxlength="4" placeholder="Год, пробелы или uuuu" @change="setCoded(11,4,$event)"></label>
<label>Язык<select :value="codedPart(35,3)||'|||'" @change="setCoded(35,3,$event)"><option v-if="codedPart(35,3)&&!['|||','rus','kaz','eng','mul','und','zxx'].includes(codedPart(35,3))" :value="codedPart(35,3)">Исходный код: {{codedPart(35,3)}}</option><option value="|||">Не кодировать</option><option value="rus">Русский</option><option value="kaz">Казахский</option><option value="eng">Английский</option><option value="mul">Несколько языков</option><option value="und">Не определён</option><option value="zxx">Без языкового содержания</option></select></label>
<label>Место издания<select :value="codedPart(15,3)||'|||'" @change="setCoded(15,3,$event)"><option v-if="codedPart(15,3)&&!['|||','kz ','ru ','xx ','vp '].includes(codedPart(15,3))" :value="codedPart(15,3)">Исходный код: {{codedPart(15,3)}}</option><option value="|||">Не кодировать</option><option value="kz ">Казахстан</option><option value="ru ">Россия</option><option value="xx ">Место неизвестно</option><option value="vp ">Разные места</option></select></label><label>Другое место — код MARC<input :value="codedPart(15,3)" maxlength="3" placeholder="Код из справочника MARC" @change="setCoded(15,3,$event)"></label><p>Код места издания не всегда совпадает с ISO-кодом страны. Специальные характеристики материала доступны в полной записи; здесь они не перезаписываются.</p>
</section></td></tr><template v-if="expanded.has(uid(f))||specs[f.tag]?.local">
<tr v-for="s in extra(f)" :key="uid(s)" class="subfield-row" @contextmenu="openMenu($event,f,s)"><td class="code subcode">${{s.code}}</td><td>{{sfLabel(f,s)}}</td><td><div class="value-cell"><VocabularyInput :readonly="technical(f,s)" v-model="s.value" :ariaLabel="f.tag+'$'+s.code+' '+sfLabel(f,s)" :placeholder="sfLabel(f,s)" :settings="vocabSettings(f,s.code)" :entries="vocabEntries(f,s.code)" @enter="nextInput" /><button class="dots" :aria-label="'Действия с подполем '+f.tag+'$'+s.code" @click.stop="openMenu($event,f,s)">⋯</button></div></td></tr>
<tr class="field-tools" v-if="!specs[f.tag]?.local||expanded.has(uid(f))"><td></td><td colspan="2"><div class="inline-tools"><select :value="addCode[uid(f)]||''" @change="addCode[uid(f)]=($event.target as HTMLSelectElement).value" :aria-label="'Добавить подполе '+f.tag"><option value="">Выберите дополнительное подполе</option><option v-for="s in options(f)" :value="s.code">${{s.code}} · {{specs[f.tag]?.local?s.label:subName(f.tag,s.code,s.label)}}</option></select><button :disabled="!options(f).length||!addCode[uid(f)]" @click="addSub(f)">＋ Добавить</button><details class="indicators"><summary>Индикаторы</summary><div v-for="position in [1,2]" class="indicator-control"><label>{{position}} · {{ru(specs[f.tag]?.indicators.find(i=>i.position===position)?.label)}}<select v-if="position===1" v-model="f.ind1"><option v-if="!specs[f.tag]?.indicators.find(i=>i.position===1)?.values.some(v=>v.code===f.ind1)" :value="f.ind1">{{f.ind1===' '?'Пробел':f.ind1}}</option><option v-for="v in specs[f.tag]?.indicators.find(i=>i.position===1)?.values" :value="v.code">{{v.code===' '?'Пробел':v.code}} · {{ru(v.label)}}</option></select><select v-else v-model="f.ind2"><option v-if="!specs[f.tag]?.indicators.find(i=>i.position===2)?.values.some(v=>v.code===f.ind2)" :value="f.ind2">{{f.ind2===' '?'Пробел':f.ind2}}</option><option v-for="v in specs[f.tag]?.indicators.find(i=>i.position===2)?.values" :value="v.code">{{v.code===' '?'Пробел':v.code}} · {{ru(v.label)}}</option></select></label></div></details></div></td></tr>
</template></tbody></table>
<div class="empty" v-if="!visible.length"><h2>Рабочий лист пуст</h2><p>Выберите поля на вкладке «Настройка ввода».</p><button @click="page='types';selectProfile(activeType)">Настроить поля</button></div></div>
<div class="restore-fields" v-if="activeType?.config.some(c=>!visible.some(f=>f.tag===c.tag))"><span>Вернуть строку:</span><button v-for="c in activeType?.config.filter(c=>!visible.some(f=>f.tag===c.tag))" @click="restore(c.tag)">＋ {{c.tag}} {{c.label||fieldName(c.tag,specs[c.tag]?.label)}}</button></div>
<section class="card gost-panel"><div class="page-heading"><div><h2>Библиографическое описание · ГОСТ Р 7.0.100–2018</h2><p>Порядок областей описания отличается от порядка строк рабочего листа.</p></div><button @click="buildGost" :disabled="busy">Сформировать описание</button></div><label>Вид описания<select v-model="gostKind" aria-label="Вид описания"><option value="single">Одноуровневое описание</option><option value="component">Составная часть (статья)</option></select></label><template v-if="gostPreview"><p v-if="gostStale" class="unsaved">Запись изменена. Сформируйте описание заново.</p><blockquote>{{gostPreview.text||'Заполните сведения о документе.'}}</blockquote><p><b>Черновик для проверки каталогизатором.</b> {{gostPreview.scope}}</p><ul><li v-for="issue in gostPreview.issues">{{issue.message}} <small>ГОСТ, п. {{issue.clause}}</small></li></ul></template></section><div class="editor-footer"><span v-if="hidden" class="muted">Дополнительных скрытых полей: {{hidden}}. Их данные сохраняются.</span><details><summary>Служебные данные записи</summary><label>Маркер записи<input class="mono" :value="editor.marc.leader" readonly></label><button @click="openRaw">Полная запись JSON</button></details><span class="muted">Ctrl / ⌘ + S — сохранить</span></div>
</fieldset>
</section>
<UsersPage v-if="page==='users'&&currentUser.role==='admin'" :api="api" :currentId="currentUser.id" @selfChanged="signedOut" />
<WithdrawalsPage v-if="page==='withdrawals'&&can('withdrawals.view')" :canCreate="can('withdrawals.create')" :api="api" />
<CirculationPage v-if="page==='circulation'" :api="api" :can="can" />
<ReadersPage v-if="page==='readers'&&can('readers.registry.view')" ref="readersPage" :api="api" :can="can" :is-admin="currentUser.role==='admin'" @visit="openVisit" />
<VisitsPage v-if="page==='visits'&&(can('visits.record')||can('visits.view'))" :api="api" :can="can" :initial-code="visitCode" @reader="openReader" />
<StatisticsPage v-if="page==='statistics'&&can('statistics.view')" :api="api" @record="openKsuRecord" />
<KsuPage v-if="page==='ksu'&&can('ksu.view')" :canEdit="can('ksu.edit')" :api="api" @record="openKsuRecord" @receipt="openKsuReceipt" />
<AcquisitionsPage ref="acquisitionsPage" v-if="page==='acquisitions'&&can('acquisitions.view')" :canEdit="can('acquisitions.edit')" :canCancel="can('acquisitions.cancel')" :api="api" />
<section v-if="page==='types'&&can('settings.edit')">
<div class="page-heading"><div><div class="eyebrow">РАБОЧИЕ ЛИСТЫ</div><h1>Настройка ввода</h1><p>Какие строки видит каталогизатор и в каком порядке их заполняет.</p></div><button class="primary" :disabled="busy||!profile.name.trim()" @click="saveProfile">Сохранить настройки</button></div>
<SettingsTransfer :api="api" @imported="refreshSettings" />
<div class="card type-toolbar"><label>Тип документа<select :value="profile.id" @change="configChanged" aria-label="Тип документа"><option :value="0">Новый тип документа</option><option v-for="t in types" :value="t.id">{{t.name}}</option></select></label><label>Название типа<input v-model="profile.name" placeholder="Например, Диссертация"></label><button @click="selectProfile()">＋ Создать тип</button></div>
<div class="settings-grid"><div class="card"><div class="section-heading"><h2>Строки рабочего листа <span class="counter">{{profile.config.length}}</span></h2><p>Порядок сверху вниз соответствует последовательности ввода.</p></div><div class="selected-fields"><div v-for="(c,i) in profile.config" :key="c.tag" class="config-field" :data-config-field="c.tag"><div class="config-line"><span class="position">{{i+1}}</span><span class="code">{{c.tag}}</span><input v-model="c.label" :placeholder="fieldName(c.tag,specs[c.tag]?.label)" :aria-label="'Название строки '+c.tag"><button class="icon-button" :disabled="i===0" :aria-label="'Поднять поле '+c.tag" @click="move(profile.config,i,-1)">↑</button><button class="icon-button" :disabled="i===profile.config.length-1" :aria-label="'Опустить поле '+c.tag" @click="move(profile.config,i,1)">↓</button><button class="icon-button" :aria-label="'Скрыть поле '+c.tag" @click="toggle(c.tag)">×</button></div><div class="config-meta"><label class="check-label"><input type="checkbox" v-model="c.required">Обязательное</label><span>{{specs[c.tag]?.repeatable?'Можно повторять':'Без повторений'}}</span></div><details class="subfield-settings"><summary>Подполя: {{c.subfields.length?'выбрано '+c.subfields.length:'основные по умолчанию'}}</summary><p>Отметьте нужные подполя в порядке ввода. Без выбора показываются основные, остальные можно добавить в записи.</p><div v-if="c.subfields.length" class="chosen-subfields"><div v-for="(code,j) in c.subfields" :key="code"><span class="code">${{code}}</span><span>{{specs[c.tag]?.local?specs[c.tag]?.subfields.find(s=>s.code===code)?.label:subName(c.tag,code,specs[c.tag]?.subfields.find(s=>s.code===code)?.label)}}</span><button :disabled="j===0" :aria-label="'Поднять подполе '+c.tag+'$'+code" @click="move(c.subfields,j,-1)">↑</button><button :disabled="j===c.subfields.length-1" :aria-label="'Опустить подполе '+c.tag+'$'+code" @click="move(c.subfields,j,1)">↓</button></div></div><label v-for="s in specs[c.tag]?.subfields" class="check-label"><input type="checkbox" v-model="c.subfields" :value="s.code"><span class="code">${{s.code}}</span>{{specs[c.tag]?.local?s.label:subName(c.tag,s.code,s.label)}}</label></details><VocabularySettings v-if="!['000','001','005','008'].includes(c.tag)" :config="c" :spec="specs[c.tag]" :typeId="profile.id" :api="api" /></div><div class="empty" v-if="!profile.config.length"><h2>Выберите поля справа</h2><p>Начните с заглавия, автора и выходных данных.</p></div></div></div>
<div class="card field-picker"><div class="section-heading"><h2>Добавить поля</h2><input v-model="fieldQuery" placeholder="Код или название на русском" aria-label="Найти поле"><label class="check-label"><input type="checkbox" v-model="showObsolete">Показать устаревшие</label></div><div class="picker-list"><label v-for="f in available" :key="f.tag" :class="{picked:profile.config.some(c=>c.tag===f.tag)}"><input type="checkbox" :checked="profile.config.some(c=>c.tag===f.tag)" @change="toggle(f.tag)"><span class="code">{{f.tag}}</span><span>{{f.local?f.label:fieldName(f.tag,f.label)}}<small v-if="f.obsolete">Устаревшее поле</small></span></label></div></div></div>
</section>
<section v-if="page==='reference'"><div class="page-heading"><div><div class="eyebrow">СПРАВОЧНИК MARC21</div><h1>Поля библиографической записи</h1><p>Русские названия, подполя и правила повторения.</p></div><span class="pill">{{dictionary.length}} полей</span></div><div class="reference-grid"><div class="card field-picker"><div class="section-heading"><input v-model="fieldQuery" placeholder="Код или название" aria-label="Поиск по справочнику"><label class="check-label"><input type="checkbox" v-model="showObsolete">Показать устаревшие</label></div><div class="picker-list"><button v-for="f in available" :class="{picked:referenceTag===f.tag}" @click="referenceTag=f.tag"><span class="code">{{f.tag}}</span>{{f.local?f.label:fieldName(f.tag,f.label)}}</button></div></div><div v-if="refSpec" class="card reference-detail"><div class="eyebrow">ПОЛЕ {{refSpec.tag}}</div><h2>{{fieldName(refSpec.tag,refSpec.label)}}</h2><p><span class="pill">{{refSpec.repeatable?'Можно повторять':'Без повторений'}}</span><span v-if="refSpec.obsolete" class="pill">Устаревшее</span></p><h3>Подполя</h3><table><thead><tr><th>Код</th><th>Название</th><th>Повторение</th></tr></thead><tbody><tr v-for="s in refSpec.subfields"><td class="code">${{s.code}}</td><td>{{subName(refSpec.tag,s.code,s.label)}}</td><td>{{s.repeatable?'Да':'Нет'}}</td></tr></tbody></table><div v-for="ind in refSpec.indicators"><h3>Индикатор {{ind.position}} · {{ru(ind.label)}}</h3><p v-for="v in ind.values"><span class="code">{{v.code===' '?'Пробел':v.code}}</span> — {{ru(v.label)}}</p></div><details><summary>Оригинал описания на английском</summary><pre>{{refSpec.documentation}}</pre></details><a href="https://www.loc.gov/marc/bibliographic/ecbdlist.html" target="_blank" rel="noreferrer">Официальный источник MARC21 ↗</a></div></div></section>
</template>
<div v-if="error" role="alert" class="toast error"><b>Проверьте данные</b><div>{{error}}</div><button @click="error=''" aria-label="Закрыть сообщение">×</button></div><div v-if="message" role="status" class="toast success">✓ {{message}}<button @click="message=''" aria-label="Закрыть сообщение">×</button></div><div v-if="busy" class="loading" role="status">Обработка…</div>
</main></div></div>
<div v-if="menu" class="context-menu" role="menu" :style="{left:menu.x+'px',top:menu.y+'px'}" @click.stop><div class="menu-title">{{menu.field.tag}}{{menu.sub?'$'+menu.sub.code:''}} · {{menu.sub?'Подполе':'Поле'}}</div><button role="menuitem" :disabled="!canRepeat()" @click="duplicate">⧉ Дублировать {{menu.sub?'подполе':'поле'}}<small v-if="!canRepeat()">Повторение не допускается</small></button><button role="menuitem" :disabled="!canRemove()" @click="remove">× Удалить {{menu.sub?'подполе':'поле'}}<small v-if="!canRemove()">Обязательная строка</small></button><button v-if="!menu.sub" role="menuitem" @click="toggleDetails(menu.field);menu=null">☷ Подполя и уточнения</button></div>
<div v-if="rawOpen" class="modal-backdrop"><section class="modal card" role="dialog" aria-modal="true" aria-label="Полная запись"><h2>Полная запись</h2><p>Служебный режим: все поля, включая скрытые и локальные.</p><textarea v-model="raw" rows="18" aria-label="Полная MARC запись"></textarea><div class="modal-actions"><button @click="rawOpen=false">Отмена</button><button class="primary" @click="applyRaw">Применить к рабочему листу</button></div></section></div>
<div v-if="confirmClose" class="modal-backdrop"><section class="modal small card" role="dialog" aria-modal="true" aria-label="Несохранённые изменения"><h2>Сохранить изменения?</h2><p>В рабочем листе остались несохранённые данные.</p><div class="modal-actions"><button @click="confirmClose=false">Продолжить ввод</button><button @click="editor=null;confirmClose=false">Закрыть без сохранения</button><button class="primary" :disabled="busy" @click="saveRecord().then(()=>{if(!error){editor=null;confirmClose=false;}})">Сохранить</button></div></section></div>
<dialog ref="deleteDialog" class="modal small card record-delete-dialog" aria-labelledby="delete-title" @cancel="busy?$event.preventDefault():deleteTarget=null" @close="deleteTarget=null"><template v-if="deleteTarget"><h2 id="delete-title">Удалить запись из каталога?</h2><p><strong>{{title(deleteTarget)}}</strong><br>Запись №{{deleteTarget.id}}</p><p>Удаление необратимо. Тип документа и справочники останутся. Несохранённые изменения этой записи будут потеряны.</p><p v-if="error" role="alert" class="delete-error">{{error}}</p><div class="modal-actions"><button autofocus :disabled="busy" @click="deleteTarget=null">Отмена</button><button class="danger-button" :disabled="busy" @click="deleteRecord">Удалить запись</button></div></template></dialog>
</template>
